/**
 * MonthlyReportEditor — orchestrator for monthly incident recommendation report.
 */
import React from 'react';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  ArcElement,
  Tooltip,
  Legend,
} from 'chart.js';
import type { MonthlyReportSectionTab } from './monthlyReportEditorShared';
import type { MonthlyReportEditorProps } from './monthlyReportEditorTypes';
import { useMonthlyReportEditor } from './useMonthlyReportEditor';
import { MonthlyReportEditorToolbar } from './MonthlyReportEditorToolbar';
import { MonthlyReportEditorChrome } from './MonthlyReportEditorChrome';
import { MonthlyReportSectionSummary } from './MonthlyReportSectionSummary';
import { MonthlyReportSectionAnalysis } from './MonthlyReportSectionAnalysis';
import { MonthlyReportSectionRpn } from './MonthlyReportSectionRpn';
import { MonthlyReportSectionSolution } from './MonthlyReportSectionSolution';
import { MonthlyReportEditorOverlays } from './MonthlyReportEditorOverlays';
import s from './MonthlyReportEditor.module.css';

export type { MonthlyReportSectionTab };

ChartJS.register(CategoryScale, LinearScale, BarElement, ArcElement, Tooltip, Legend);

export const MonthlyReportEditor: React.FC<MonthlyReportEditorProps> = (props) => {
  const {
    hideSectionTabs = false,
    lockPeriod = false,
    onPeriodChange,
  } = props;

  const vm = useMonthlyReportEditor(props);

  return (
    <div className={s.wrapper}>
      <MonthlyReportEditorToolbar
        draftLoading={vm.draftLoading}
        activeRpnCount={vm.activeRpnCount}
        periodLabel={vm.periodLabel}
        displayReportCode={vm.displayReportCode}
        reportNumber={vm.reportNumber}
        onReportNumberChange={vm.onReportNumberChange}
        readOnly={vm.readOnly}
        draftSaving={vm.draftSaving}
        effectiveDateFrom={vm.effectiveDateFrom}
        effectiveDateTo={vm.effectiveDateTo}
        handleSaveDraft={vm.handleSaveDraft}
        handleSubmit={vm.handleSubmit}
        handleDelete={vm.handleDelete}
        handleApprove={vm.handleApprove}
        handleCancel={vm.handleCancel}
        permissions={vm.permissions}
        showAiButton={vm.showAiButton}
        isAiEnabled={vm.isAiEnabled}
        aiLoading={vm.aiLoading}
        creditLoading={vm.creditLoading}
        handleAiAnalyze={vm.handleAiAnalyze}
        creditCheck={vm.creditCheck}
        nativeMob={vm.nativeMob}
        openPreview={vm.openPreview}
        onPrintClick={vm.onPrintClick}
        onExportWordClick={vm.onExportWordClick}
        exportingWord={vm.exportingWord}
        preparingPrint={vm.preparingPrint}
        draftStatus={vm.draftStatus}
      />

      <MonthlyReportEditorChrome
        localDateFrom={vm.localDateFrom}
        localDateTo={vm.localDateTo}
        effectiveDateFrom={vm.effectiveDateFrom}
        effectiveDateTo={vm.effectiveDateTo}
        periodLabel={vm.periodLabel}
        lockPeriod={lockPeriod}
        readOnly={vm.readOnly}
        localIncludeDraft={vm.localIncludeDraft}
        showIncludeDraft={!!onPeriodChange}
        onDateFromChange={vm.onDateFromChange}
        onDateToChange={vm.onDateToChange}
        onIncludeDraftChange={vm.onIncludeDraftChange}
        onSearch={vm.handleSearch}
        validationErrors={vm.validationErrors}
        isAiEnabled={vm.isAiEnabled}
        aiDraftApplied={vm.aiDraftApplied}
        hideSectionTabs={hideSectionTabs}
        activeSection={vm.activeSection}
        onSectionChange={vm.setActiveSection}
      />

      {vm.activeSection === 'summary' && (
        <MonthlyReportSectionSummary
          report={vm.report}
          effectiveDateFrom={vm.effectiveDateFrom}
          effectiveDateTo={vm.effectiveDateTo}
          voluntaryCount={vm.voluntaryCount}
          mandatoryCount={vm.mandatoryCount}
          departments={vm.departments}
          clinicalCount={vm.clinicalCount}
          serviceCount={vm.serviceCount}
          fallCount={vm.fallCount}
          summaryItems={vm.summaryItems}
          summaryLoading={vm.summaryLoading}
        />
      )}

      <MonthlyReportSectionAnalysis
        visible={vm.activeSection === 'analysis'}
        forceChartsMount={vm.forceChartsMount}
        readOnly={vm.readOnly}
        activeTypeGroups={vm.activeTypeGroups}
        activeCauseGroups={vm.activeCauseGroups}
        ncGroups={vm.ncGroups}
        typeGroupChartType={vm.typeGroupChartType}
        occurrenceChartType={vm.occurrenceChartType}
        causeGroupChartType={vm.causeGroupChartType}
        typeGroupText={vm.typeGroupText}
        occurrenceText={vm.occurrenceText}
        causeGroupText={vm.causeGroupText}
        onChartTypeChange={vm.onChartTypeChange}
        setTypeGroupChartType={vm.setTypeGroupChartType}
        setOccurrenceChartType={vm.setOccurrenceChartType}
        setCauseGroupChartType={vm.setCauseGroupChartType}
        onAnalysisTextChange={vm.onAnalysisTextChange}
        setTypeGroupText={vm.setTypeGroupText}
        setOccurrenceText={vm.setOccurrenceText}
        setCauseGroupText={vm.setCauseGroupText}
        captureTypeGroup={vm.captureTypeGroup}
        captureOccurrence={vm.captureOccurrence}
        captureCauseGroup={vm.captureCauseGroup}
      />

      {vm.activeSection === 'rpn' && (
        <MonthlyReportSectionRpn
          readOnly={vm.readOnly}
          rpnRows={vm.rpnRows}
          updateRpn={vm.updateRpn}
          addRpnRow={vm.addRpnRow}
          removeRpnRow={vm.removeRpnRow}
        />
      )}

      {vm.activeSection === 'solution' && (
        <MonthlyReportSectionSolution
          readOnly={vm.readOnly}
          rpnRows={vm.rpnRows}
          updateRpn={vm.updateRpn}
        />
      )}

      <MonthlyReportEditorOverlays
        report={vm.report}
        printRef={vm.printRef}
        previewScrollRef={vm.previewScrollRef}
        effectiveFilters={vm.effectiveFilters}
        rpnRows={vm.rpnRows}
        chartImages={vm.chartImages}
        displayReportCode={vm.displayReportCode}
        reportNumber={vm.reportNumber}
        effectiveOverride={vm.effectiveOverride}
        aiDraftApplied={vm.aiDraftApplied}
        summaryItems={vm.summaryItems}
        showPreview={vm.showPreview}
        setShowPreview={vm.setShowPreview}
        zoom={vm.zoom}
        periodLabel={vm.periodLabel}
        onPrintClick={vm.onPrintClick}
        onExportWordClick={vm.onExportWordClick}
        exportingWord={vm.exportingWord}
        preparingPrint={vm.preparingPrint}
        isAiEnabled={vm.isAiEnabled}
        showCreditModal={vm.showCreditModal}
        setShowCreditModal={vm.setShowCreditModal}
        creditCheck={vm.creditCheck}
        suggestedPacks={vm.suggestedPacks}
      />
    </div>
  );
};
