import React from 'react';
import type { ValidationErrors } from '../../../utils/formValidation';
import type { MonthlyReportSectionTab } from './monthlyReportEditorShared';
import s from './MonthlyReportEditor.module.css';

interface Props {
  localDateFrom: string;
  localDateTo: string;
  effectiveDateFrom: string;
  effectiveDateTo: string;
  periodLabel: string;
  lockPeriod: boolean;
  readOnly: boolean;
  localIncludeDraft: boolean;
  showIncludeDraft: boolean;
  onDateFromChange: (value: string) => void;
  onDateToChange: (value: string) => void;
  onIncludeDraftChange: (checked: boolean) => void;
  onSearch: () => void;
  validationErrors: ValidationErrors;
  isAiEnabled: boolean;
  aiDraftApplied: boolean;
  hideSectionTabs: boolean;
  activeSection: MonthlyReportSectionTab;
  onSectionChange: (tab: MonthlyReportSectionTab) => void;
}

export const MonthlyReportEditorChrome: React.FC<Props> = ({
  localDateFrom,
  localDateTo,
  effectiveDateFrom,
  effectiveDateTo,
  periodLabel,
  lockPeriod,
  readOnly,
  localIncludeDraft,
  showIncludeDraft,
  onDateFromChange,
  onDateToChange,
  onIncludeDraftChange,
  onSearch,
  validationErrors,
  isAiEnabled,
  aiDraftApplied,
  hideSectionTabs,
  activeSection,
  onSectionChange,
}) => (
  <>
    <div className={s.filterBar} id="monthly-report-filter-bar">
      <div className={s.filterBarLabel}>
        <i className="fas fa-calendar-alt" />
        Kỳ báo cáo:
      </div>
      <div className={s.filterBarGroup}>
        <label className={s.filterBarFieldLabel}>Từ ngày</label>
        <input
          className={s.filterDateInput}
          type="date"
          value={localDateFrom}
          disabled={readOnly}
          onChange={(e) => onDateFromChange(e.target.value)}
        />
      </div>
      <div className={s.filterBarGroup}>
        <label className={s.filterBarFieldLabel}>Đến ngày</label>
        <input
          className={s.filterDateInput}
          type="date"
          value={localDateTo}
          disabled={readOnly}
          onChange={(e) => onDateToChange(e.target.value)}
        />
      </div>
      {effectiveDateFrom && effectiveDateTo && (
        <span className={s.filterBarPeriodBadge}>
          <i className="fas fa-check-circle" style={{ color: '#10b981', marginRight: 4 }} />
          {periodLabel}
        </span>
      )}
      {lockPeriod && (
        <span className={s.filterBarHint} title="Kỳ khóa khi chỉnh sửa bản lưu">
          <i className="fas fa-lock" style={{ marginRight: 4 }} />
          Kỳ đã khóa
        </span>
      )}
      {(!effectiveDateFrom || !effectiveDateTo) && !lockPeriod && (
        <span className={s.filterBarHint}>Chọn kỳ để tải dữ liệu</span>
      )}
      {showIncludeDraft && (
        <label className={s.filterBarDraftToggle}>
          <input
            type="checkbox"
            checked={localIncludeDraft}
            disabled={readOnly}
            onChange={(e) => onIncludeDraftChange(e.target.checked)}
          />
          Bao gồm sự cố nháp
        </label>
      )}
      <button
        type="button"
        className={s.filterSearchBtn}
        disabled={readOnly}
        onClick={onSearch}
        title="Tìm kiếm và tải dữ liệu theo kỳ đã chọn"
      >
        <i className="fas fa-search" />
        Tìm
      </button>
    </div>

    {(validationErrors.dateFrom || validationErrors.dateTo) && (
      <div className={s.validationBanner} role="alert">
        <i className="fas fa-exclamation-circle" />
        {validationErrors.dateFrom ?? validationErrors.dateTo}
      </div>
    )}

    {validationErrors.rpnRows && (
      <div className={s.validationBanner} role="alert">
        <i className="fas fa-exclamation-circle" />
        {validationErrors.rpnRows}
      </div>
    )}

    {isAiEnabled && aiDraftApplied && (
      <div className={s.aiDraftNotice} data-testid="medical-report-ai-draft-notice">
        <i className="fas fa-exclamation-triangle" />
        <span>
          Bản nháp AI đã được áp dụng. Rà soát và chỉnh sửa nội dung trước khi in hoặc trình ký.
        </span>
      </div>
    )}

    {!hideSectionTabs && (
      <div className={s.sectionTabs}>
        {([
          ['summary', 'fas fa-list-alt', 'Mục 1 — Tổng hợp'],
          ['analysis', 'fas fa-chart-pie', 'Mục 2 — Phân tích'],
          ['rpn', 'fas fa-exclamation-triangle', 'Mục 3 — Trầm trọng'],
          ['solution', 'fas fa-lightbulb', 'Mục 4 — Đề xuất'],
        ] as const).map(([id, icon, label]) => (
          <button
            key={id}
            type="button"
            className={`${s.sectionTab} ${activeSection === id ? s.sectionTabActive : ''}`}
            onClick={() => onSectionChange(id)}
          >
            <i className={icon} /> {label}
          </button>
        ))}
      </div>
    )}
  </>
);
