/**
 * MonthlyReportFormPage — full-page standalone editor for a monthly incident report.
 *
 * Routes:
 *   /medical-incidents/monthly-reports/new          → create (defaults to current month)
 *   /medical-incidents/monthly-reports/:id          → edit existing draft by ID
 */
import React, { useCallback, useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import { useAppNavigate } from '../../hooks/useAppNavigate';
import { scykRoutes } from '../../config/scykRoutes';
import { Tabs, LeaveConfirmModal } from '@linm-soft-org/linm-web-common-components';
import { useFormLeaveGuard } from '@linm-soft-org/linm-web-common-components';
import { medicalIncidentEndpoint } from '../../services/medicalIncidents/endpoint';
import { medicalIncidentService }  from '../../services/medicalIncidents/medicalIncidentService';
import type {
  MedicalIncidentReport,
  MedicalIncidentReportFilters,
  MonthlyIncidentReportDraft,
  SaveMonthlyIncidentReportPayload,
} from '../../models/MedicalIncident';
import {
  MonthlyReportEditor,
  type MonthlyReportSectionTab,
} from './components/MonthlyReportEditor';
import { useAppToast } from '../../hooks/useAppToast';
import { useMonthlyReportPermissions } from '../../hooks/useMonthlyReportPermissions';
import styles from './MonthlyReportFormPage.module.css';

function emptyReport(): MedicalIncidentReport {
  return {
    dateFrom:               '',
    dateTo:                 '',
    totalCount:             0,
    byMonth:                [],
    byReportType:           [],
    byReportingDepartment:  [],
    byDepartment:           [],
    byOccurrenceStatus:     [],
    bySeverity:             [],
    byAffectedSubject:      [],
    byRelatedProcess:       [],
    byFallIncident:         [],
    byServiceMismatch:      [],
    byIncidentTypeGroup:      [],
    incidentTypeGroupDetails: [],
    byCauseGroup:           [],
    causeGroupDetails:      [],
    bySituationProgress:    [],
    byInjuryNc:             [],
    byOrgInjury:            [],
  };
}

function getCurrentMonthRange(): { dateFrom: string; dateTo: string } {
  const now = new Date();
  const y = now.getFullYear();
  const m = now.getMonth();
  return {
    dateFrom: new Date(y, m, 1).toLocaleDateString('en-CA'),
    dateTo:   new Date(y, m + 1, 0).toLocaleDateString('en-CA'),
  };
}

function periodLabel(dateFrom?: string, dateTo?: string) {
  if (!dateFrom || !dateTo) return 'Kỳ báo cáo';
  const from = new Date(dateFrom + 'T00:00:00');
  const to   = new Date(dateTo   + 'T00:00:00');
  if (from.getFullYear() === to.getFullYear() && from.getMonth() === to.getMonth())
    return `Tháng ${from.getMonth() + 1}/${from.getFullYear()}`;
  return `${from.toLocaleDateString('vi-VN')} – ${to.toLocaleDateString('vi-VN')}`;
}

const SECTION_TABS = [
  { id: 'summary',  label: 'Mục 1 — Tổng hợp',     icon: 'fas fa-list-alt' },
  { id: 'analysis', label: 'Mục 2 — Phân tích',    icon: 'fas fa-chart-pie' },
  { id: 'rpn',      label: 'Mục 3 — Trầm trọng',   icon: 'fas fa-exclamation-triangle' },
  { id: 'solution', label: 'Mục 4 — Đề xuất',      icon: 'fas fa-lightbulb' },
];

const MonthlyReportFormPage: React.FC = () => {
  const appNavigate = useAppNavigate();
  const toast    = useAppToast();
  const { id }   = useParams<{ id: string }>();
  const isNew    = !id || id === 'new';
  const permissions = useMonthlyReportPermissions();
  const { canRead, canWrite } = permissions;

  const [draft,         setDraft]         = useState<MonthlyIncidentReportDraft | null>(null);
  const [report,        setReport]        = useState<MedicalIncidentReport>(emptyReport);
  const [filters,       setFilters]       = useState<MedicalIncidentReportFilters>(() => ({
    ...getCurrentMonthRange(),
    includeDraft: true,
  }));
  const [loading,          setLoading]          = useState(!isNew);
  const [activeSection,    setActiveSection]    = useState<MonthlyReportSectionTab>('summary');
  const { onDirtyChange, guardedNavigate, leaveConfirmModalProps } = useFormLeaveGuard({
    message: 'Báo cáo có thay đổi chưa được lưu. Rời đi sẽ mất dữ liệu đã nhập.',
  });

  const loadReportForPeriod = useCallback(async (
    dateFrom: string,
    dateTo: string,
    includeDraft = true,
  ) => {
    try {
      const r = await medicalIncidentService.getReport({ dateFrom, dateTo, includeDraft });
      setReport(r);
      setFilters({ dateFrom, dateTo, includeDraft });
    } catch (err) {
      toast.fromError(err, 'Tải thống kê báo cáo thất bại');
    }
  }, [toast]);

  const loadDraft = useCallback(async (draftId: string) => {
    setLoading(true);
    try {
      const d = await medicalIncidentEndpoint.getMonthlyReportById(draftId);
      if (!d) {
        toast.warning('Không tìm thấy báo cáo.');
        appNavigate(scykRoutes.monthlyReports.list);
        return;
      }
      setDraft(d);
      await loadReportForPeriod(d.dateFrom, d.dateTo, true);
    } catch (err) {
      toast.fromError(err, 'Tải báo cáo thất bại');
    } finally {
      setLoading(false);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [loadReportForPeriod]);

  useEffect(() => {
    if (!isNew && id) {
      const t = setTimeout(() => { void loadDraft(id); }, 0);
      return () => clearTimeout(t);
    }
    if (isNew) {
      const { dateFrom, dateTo } = getCurrentMonthRange();
      const t = setTimeout(() => { void loadReportForPeriod(dateFrom, dateTo, true); }, 0);
      return () => clearTimeout(t);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id, isNew]);

  const handlePeriodChange = useCallback((
    dateFrom: string,
    dateTo: string,
    includeDraft: boolean,
  ) => {
    void loadReportForPeriod(dateFrom, dateTo, includeDraft);
  }, [loadReportForPeriod]);

  const handleDraftMetaChange = useCallback((meta: {
    code: string;
    totalIncidents: number;
    aiDraftApplied: boolean;
  }) => {
    setDraft((prev) => ({
      id:             prev?.id ?? '',
      code:           meta.code || prev?.code || '',
      dateFrom:       filters.dateFrom ?? prev?.dateFrom ?? '',
      dateTo:         filters.dateTo   ?? prev?.dateTo   ?? '',
      reportNumber:   prev?.reportNumber ?? null,
      aiDraftApplied: meta.aiDraftApplied,
      totalIncidents: meta.totalIncidents,
      typeGroupText:  prev?.typeGroupText  ?? null,
      occurrenceText: prev?.occurrenceText ?? null,
      causeGroupText: prev?.causeGroupText ?? null,
      typeGroupChartType:  prev?.typeGroupChartType  ?? 'doughnut',
      occurrenceChartType: prev?.occurrenceChartType ?? 'doughnut',
      causeGroupChartType: prev?.causeGroupChartType ?? 'doughnut',
      rpnRows:   prev?.rpnRows   ?? [],
      status:    prev?.status ?? 'Draft',
      createdAt: prev?.createdAt ?? new Date().toISOString(),
      updatedAt: prev?.updatedAt ?? new Date().toISOString(),
    }));
  }, [filters.dateFrom, filters.dateTo]);

  const handleSaveSuccess = useCallback((saved: MonthlyIncidentReportDraft) => {
    setDraft(saved);
    if (isNew && saved.id) {
      appNavigate(scykRoutes.monthlyReports.detail(saved.id), { replace: true });
    }
  }, [isNew, appNavigate]);

  const handleSubmit = useCallback(async (
    payload: SaveMonthlyIncidentReportPayload,
  ) => {
    try {
      const saved = await medicalIncidentEndpoint.submitMonthlyReport(payload);
      setDraft(saved);
      toast.success('Đã gửi báo cáo thành công');
    } catch (err) {
      toast.fromError(err, 'Gửi báo cáo thất bại');
    }
  }, [toast]);

  const handleDelete = useCallback(async (reportId: string) => {
    try {
      await medicalIncidentEndpoint.deleteMonthlyReport(reportId);
      toast.success('Đã xóa báo cáo');
      appNavigate(scykRoutes.monthlyReports.list);
    } catch (err) {
      toast.fromError(err, 'Xóa báo cáo thất bại');
    }
  }, [appNavigate, toast]);

  const handleApprove = useCallback(async (reportId: string) => {
    try {
      const saved = await medicalIncidentEndpoint.approveMonthlyReport(reportId);
      setDraft(saved);
      toast.success('Đã duyệt báo cáo');
    } catch (err) {
      toast.fromError(err, 'Duyệt báo cáo thất bại');
    }
  }, [toast]);

  const handleCancel = useCallback(async (reportId: string) => {
    try {
      const saved = await medicalIncidentEndpoint.cancelMonthlyReport(reportId);
      setDraft(saved);
      toast.success('Đã hủy gửi báo cáo');
    } catch (err) {
      toast.fromError(err, 'Hủy gửi báo cáo thất bại');
    }
  }, [toast]);

  const handleBack = () => {
    guardedNavigate(() => appNavigate(scykRoutes.monthlyReports.list));
  };

  const code   = draft?.code;
  const period = periodLabel(filters.dateFrom, filters.dateTo);
  const isFinalStatus = draft?.status === 'Submitted' || draft?.status === 'Approved';

  if (!canRead) {
    return (
      <div className={styles.loadingState}>
        <i className="fas fa-lock" style={{ fontSize: 24, marginBottom: 12 }} />
        <span>Bạn không có quyền xem báo cáo tổng hợp hàng tháng.</span>
      </div>
    );
  }

  if (loading && !isNew) {
    return (
      <div className={styles.loadingState}>
        <i className="fas fa-spinner fa-spin" style={{ fontSize: 24, marginBottom: 12 }} />
        <span>Đang tải báo cáo...</span>
      </div>
    );
  }

  return (
    <div className={styles.page}>
      <div className={styles.stickyTop}>
        <div className={styles.pageHeader}>
          <div className={styles.titleGroup}>
            <button type="button" className={styles.backBtn} onClick={handleBack}>
              ← Quay lại
            </button>
            <div>
              <div className={styles.titleRow}>
                <i className="fas fa-file-medical-alt" style={{ color: '#0066cc', marginRight: 8 }} />
                <h1 className={styles.title}>
                  {isNew ? 'Báo cáo tổng hợp mới' : 'Báo cáo tổng hợp hàng tháng'}
                </h1>
                {code && <span className={styles.codeBadge}>{code}</span>}
              </div>
              <div className={styles.subTitle}>
                <i className="fas fa-calendar-alt" style={{ marginRight: 5, color: '#64748b' }} />
                {period}
              </div>
            </div>
          </div>
          <div className={styles.headerMeta}>
            {(draft?.totalIncidents ?? report.totalCount) > 0 && (
              <span className={styles.metaBadge}>
                <i className="fas fa-exclamation-circle" />
                {draft?.totalIncidents ?? report.totalCount} sự cố
              </span>
            )}
            {draft?.aiDraftApplied && (
              <span className={styles.metaBadgeAi}>
                <i className="fas fa-robot" /> AI
              </span>
            )}
          </div>
        </div>

        <div className={styles.tabsWrapper}>
          <Tabs
            tabs={SECTION_TABS}
            activeTab={activeSection}
            onTabChange={(tab) => setActiveSection(tab as MonthlyReportSectionTab)}
            variant="default"
          />
        </div>
      </div>

      <div className={styles.tabContent}>
        <MonthlyReportEditor
          report={report}
          filters={filters}
          reportCode={code}
          initialDraft={!isNew ? draft : null}
          activeSection={activeSection}
          onSectionChange={setActiveSection}
          hideSectionTabs
          onPeriodChange={handlePeriodChange}
          onDraftMetaChange={handleDraftMetaChange}
          onSaveSuccess={handleSaveSuccess}
          onSubmit={handleSubmit}
          onDelete={handleDelete}
          onApprove={handleApprove}
          onCancel={handleCancel}
          onDirtyChange={onDirtyChange}
          lockPeriod={!isNew}
          readOnly={!canWrite || isFinalStatus}
          permissions={permissions}
        />
      </div>

      <LeaveConfirmModal {...leaveConfirmModalProps} />
    </div>
  );
};

export default MonthlyReportFormPage;
